<?php
session_start();
require_once 'db.php';
if (!isset($_SESSION['user_id'])) { header('Location: login.html'); exit; }
$userId = (int)$_SESSION['user_id'];
$role = $_SESSION['role'] ?? '';
$paymentId = (int)($_GET['payment_id'] ?? 0);
$sql = "SELECT p.*,b.booking_code,b.category,b.subcategory,b.description,b.location,b.booking_date,b.booking_time,u.full_name customer_name,u.email customer_email,u.phone customer_phone,COALESCE(tu.full_name,b.technician_name) technician_name FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN users u ON u.id=b.user_id LEFT JOIN technicians t ON t.id=b.technician_id LEFT JOIN users tu ON tu.id=t.user_id WHERE p.id=? AND p.payment_status='success'";
if ($role === 'customer') $sql .= ' AND b.user_id=?';
$q = $conn->prepare($sql);
if ($role === 'customer') $q->bind_param('ii', $paymentId, $userId); else $q->bind_param('i', $paymentId);
$q->execute(); $voucher = $q->get_result()->fetch_assoc(); $q->close();
if (!$voucher) { http_response_code(404); die('Payment voucher not found.'); }
function h($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$methodNames = ['bkash'=>'bKash','nagad'=>'Nagad','card'=>'Card','bank_transfer'=>'Bank Transfer','cash'=>'Cash'];
?>
