<div class="vrow"><span>Voucher Number</span><strong>GBF-V-<?php echo (int)$voucher['id']; ?></strong></div><div class="vrow"><span>Payment Reference</span><strong><?php echo h($voucher['payment_reference']); ?></strong></div><div class="vrow"><span>Transaction Reference</span><strong><?php echo h($voucher['gateway_reference']); ?></strong></div><div class="vrow"><span>Payment Date</span><strong><?php echo h($voucher['payment_time']); ?></strong></div>
<h3>Customer & Booking Details</h3><div class="vrow"><span>Customer</span><strong><?php echo h($voucher['customer_name']); ?></strong></div><div class="vrow"><span>Phone / Email</span><strong><?php echo h($voucher['customer_phone'].' / '.$voucher['customer_email']); ?></strong></div><div class="vrow"><span>Booking ID</span><strong><?php echo h($voucher['booking_code'] ?: '#'.$voucher['booking_id']); ?></strong></div><div class="vrow"><span>Service</span><strong><?php echo h($voucher['category'].' / '.$voucher['subcategory']); ?></strong></div><div class="vrow"><span>Technician</span><strong><?php echo h($voucher['technician_name']); ?></strong></div><div class="vrow"><span>Service Location</span><strong><?php echo h($voucher['location']); ?></strong></div><div class="vrow"><span>Payment Method</span><strong><?php echo h($methodNames[$voucher['payment_method']] ?? ucfirst($voucher['payment_method'])); ?></strong></div><div class="vrow"><span>Payment Status</span><strong>Successful</strong></div><div class="vrow vtotal"><span>Amount Paid</span><strong>৳ <?php echo number_format((float)$voucher['amount'],2); ?> BDT</strong></div>
<p style="text-align:center;color:#666;margin-top:25px">This voucher was generated by the Ghorebaire Fix sandbox payment system. No real money was transferred.</p><div class="vbuttons"><button onclick="window.print()">Print Voucher</button><a href="dashboard.php">Back to Dashboard</a></div></main></body></html>
